// Settings → About → "Open-source licenses": the third-party components the
// app ships, grouped "In the app" (web and Android) and "Android only", each
// expanding to its full license text. Data: app/licenses.json, generated by
// scripts/make-licenses.js. A page of the settings (ui/settings.js).
import { registerPage, refreshPage, section } from "./sync-panel.js";
import { h, text } from "./dom.js";

let data = null;
let failed = false, loading = false;

async function load() {
  if (loading) return;
  loading = true;
  try {
    data = await (await fetch(new URL("../../licenses.json", import.meta.url))).json();
  } catch { failed = true; }
  refreshPage({ keepScroll: true });
}

/** How many components the list holds ("11 components"), or "" before it is loaded. */
export const licenseCount = () => data ? `${data.entries.length} components` : "";

/** Starts loading the list ahead of the page, so the settings row can show the count. */
export function preloadLicenses() { if (!data && !failed) load(); }

function item(e, texts) {
  return h("details", { class: "license-item" },
    h("summary", {}, h("span", { class: "row-title" }, e.name),
      h("span", { class: "row-sub" }, `${e.version} · ${e.license}`)),
    h("a", { class: "license-url", href: e.url, target: "_blank", rel: "noopener" }, e.url.replace(/^https:\/\//, "")),
    h("pre", { class: "license-text" }, texts[e.text]));
}

registerPage("settingsLicenses", {
  title: "Open-source licenses",
  render: () => {
    if (!data) {
      if (!failed) load();
      return [text(failed ? "The list couldn't be loaded." : "Loading…", "sheet-text muted")];
    }
    const group = platform => data.entries.filter(e => e.platform === platform);
    return [
      text("NoteDown is built on these open-source components. Tap one for its license text."),
      section("In the app"),
      h("div", { class: "sheet-card" }, group("web+android").map(e => item(e, data.texts))),
      section("Android only"),
      h("div", { class: "sheet-card" }, group("android").map(e => item(e, data.texts))),
    ];
  },
});
